plugins {
    id("org.jetbrains.kotlin.jvm")
    id("org.jetbrains.kotlin.plugin.serialization")
}
java { sourceCompatibility = JavaVersion.VERSION_17; targetCompatibility = JavaVersion.VERSION_17 }
kotlin { compilerOptions { jvmTarget.set(org.jetbrains.kotlin.gradle.dsl.JvmTarget.JVM_17) } }
dependencies {
    implementation("org.jetbrains.kotlinx:kotlinx-serialization-json:1.9.0")
    testImplementation("junit:junit:4.13.2")
}
tasks.test {
    val schema = rootProject.file("../schema")
    systemProperty("schemaDir", schema.absolutePath)
    // The shared fixtures are generated by the TS side; declare them so a regenerated fixture re-runs the tests.
    inputs.dir(schema).withPropertyName("schemaFixtures").withPathSensitivity(PathSensitivity.RELATIVE)
}
